// A fictional settings store: folders with a few values each.
const FOLDERS: TreeNode[] = [
  {
    id: "studio",
    label: "Studio",
    children: [
      { id: "studio/fonts", label: "Fonts", hasChildren: true, children: [] },
      { id: "studio/colours", label: "Colours", hasChildren: true, children: [] },
    ],
  },
  {
    id: "workspace",
    label: "Workspace",
    children: [{ id: "workspace/layout", label: "Layout", hasChildren: true, children: [] }],
  },
];
const VALUES: Record<string, Array<[string, string]>> = {
  studio: [
    ["Display name", "Northstar Studio"],
    ["Time zone", "Australia/Sydney"],
  ],
  "studio/fonts": [
    ["Interface", "Inter"],
    ["Code", "JetBrains Mono"],
  ],
  "studio/colours": [
    ["Accent", "Ocean"],
    ["Canvas", "Silk"],
  ],
  workspace: [
    ["Theme", "System"],
    ["Density", "Comfortable"],
  ],
  "workspace/layout": [
    ["Drawer", "Open"],
    ["Inspector", "Docked"],
  ],
};
// Pane limits are SplitPane props, in rem so they follow UI scale.
const EXPLORER_LIMITS = { defaultSize: "16rem", startMin: "10rem", endMin: "14rem" } as const; // tokens:allow SplitPane prop values

const STACKED_LIMITS = { startMin: "6rem", endMin: "6rem", collapseBelow: "12rem" } as const; // tokens:allow SplitPane prop values

function Values({ folder }: { folder: string }) {
  return (
    <div className="p-4">
      <FactList facts={(VALUES[folder] ?? []).map(([label, value]) => ({ label, value }))} />
    </div>
  );
}

function Explorer({
  storageKey = null,
  height = "h-80",
  startLabel = "Folders",
  endLabel = "Values",
}: {
  storageKey?: string | null;
  height?: string;
  startLabel?: string;
  endLabel?: string;
}) {
  const [folder, setFolder] = useState("studio");
  const expanded = useMemo(() => FOLDERS.map((node) => node.id), []);
  return (
    <div className={`${height} w-full rounded-tile bg-fill-muted`}>
      <SplitPane
        startLabel={startLabel}
        endLabel={endLabel}
        {...EXPLORER_LIMITS}
        storageKey={storageKey}
        start={
          <Tree
            nodes={FOLDERS}
            aria-label="Folders"
            selectableGroups
            defaultExpanded={expanded}
            selectedId={folder}
            onSelectedIdChange={(id) => id && setFolder(id)}
          />
        }
        end={<Values folder={folder} />}
      />
    </div>
  );
}

